const restoreAccount = `-- name: RestoreAccount :exec
UPDATE accounts SET deleted_at = NULL, updated_at = GREATEST(updated_at + interval '1 millisecond', $1::timestamptz), server_version = 0
WHERE id = $2 AND deleted_at IS NOT NULL
`

type RestoreAccountParams struct {
	At pgtype.Timestamptz `json:"at"`
	ID uuid.UUID          `json:"id"`
}

// GER-08: um filho aponta para um pai excluído; o servidor restaura o pai.
func (q *Queries) RestoreAccount(ctx context.Context, arg RestoreAccountParams) error {
	_, err := q.db.Exec(ctx, restoreAccount, arg.At, arg.ID)
	return err
}

